package android.view;import java.util.*;public class ViewTreeObserver{public interface OnPreDrawListener{boolean onPreDraw();}public boolean alive=true;public final List<OnPreDrawListener> listeners=new ArrayList<>();public boolean isAlive(){return alive;}public void addOnPreDrawListener(OnPreDrawListener l){listeners.add(l);}public void removeOnPreDrawListener(OnPreDrawListener l){listeners.remove(l);}public void draw(){for(var l:List.copyOf(listeners))l.onPreDraw();}}
